1	-- supabase/migrations/0000_initial_schema.sql
2	
3	-- 1. Tables
4	
5	-- teams (班テーブル)
6	create table public.teams (
7	    id serial primary key,
8	    name character varying(255) not null,
9	    created_at timestamp with time zone default now() not null
10	);
11	comment on table public.teams is '班テーブル';
12	
13	-- users (ユーザーテーブル)
14	create table public.users (
15	    id uuid references auth.users on delete cascade not null primary key,
16	    display_name character varying(255) not null unique,
17	    discord_id character varying(255) not null unique,
18	    generation integer not null,
19	    team_id integer references public.teams(id),
20	    role integer default 0 not null, -- 0: member, 1: admin
21	    card_id character varying(255) not null unique,
22	    is_active boolean default true not null,
23	    updated_at timestamp with time zone default now() not null,
24	    created_at timestamp with time zone default now() not null
25	);
26	comment on table public.users is 'ユーザーテーブル';
27	
28	-- attendances (出退勤記録)
29	create table public.attendances (
30	    id uuid default gen_random_uuid() primary key,
31	    user_id uuid references public.users(id) on delete cascade not null,
32	    type character varying(3) not null check (type in ('in', 'out')),
33	    timestamp timestamp with time zone default now() not null,
34	    date date default (now() at time zone 'utc')::date not null,
35	    created_at timestamp with time zone default now() not null
36	);
37	comment on table public.attendances is '出退勤記録';
38	
39	-- announcements (お知らせ)
40	create table public.announcements (
41	    id uuid default gen_random_uuid() primary key,
42	    title character varying(255) not null,
43	    content text not null,
44	    author_id uuid references public.users(id),
45	    is_active boolean default true not null,
46	    is_current boolean default false not null,
47	    updated_at timestamp with time zone default now() not null,
48	    created_at timestamp with time zone default now() not null
49	);
50	comment on table public.announcements is 'お知らせ';
51	-- Constraint to ensure only one announcement is current
52	create unique index announcements_is_current_true_idx on public.announcements (is_current) where is_current = true;
53	
54	-- user_edit_logs (ユーザー情報変更履歴)
55	create table public.user_edit_logs (
56	    id uuid default gen_random_uuid() primary key,
57	    target_user_id uuid references public.users(id) on delete cascade not null,
58	    editor_user_id uuid references public.users(id) on delete set null,
59	    field_name character varying(255) not null,
60	    old_value text,
61	    new_value text,
62	    created_at timestamp with time zone default now() not null
63	);
64	comment on table public.user_edit_logs is 'ユーザー情報変更履歴';
65	
66	-- daily_logout_logs (全員退勤実行ログ)
67	create table public.daily_logout_logs (
68	    id uuid default gen_random_uuid() primary key,
69	    executed_at timestamp with time zone default now() not null,
70	    affected_count integer not null,
71	    status character varying(255) not null check (status in ('success', 'error'))
72	);
73	comment on table public.daily_logout_logs is '全員退勤実行ログ';
74	
75	-- temp_registrations (仮登録テーブル)
76	create table public.temp_registrations (
77	    id uuid default gen_random_uuid() primary key,
78	    card_id character varying(255) not null unique,
79	    qr_token character varying(255) not null unique,
80	    expires_at timestamp with time zone not null,
81	    is_used boolean default false not null,
82	    accessed_at timestamp with time zone,
83	    created_at timestamp with time zone default now() not null
84	);
85	comment on table public.temp_registrations is '仮登録テーブル';
86	
87	
88	-- 2. Indexes
89	
90	-- 出退勤データの高速集計用インデックス
91	create index idx_attendances_date_user on public.attendances (date, user_id);
92	create index idx_attendances_user_timestamp on public.attendances (user_id, timestamp);
93	
94	-- カード認証用インデックス
95	-- unique constraints on users table already create indexes
96	-- create unique index idx_users_card_id on public.users (card_id);
97	-- create unique index idx_users_discord_id on public.users (discord_id);
98	
99	-- 集計用インデックス
100	create index idx_users_team_generation on public.users (team_id, generation);
101	
102	-- 仮登録管理用インデックス
103	create index idx_temp_registrations_qr_token on public.temp_registrations (qr_token);
104	create index idx_temp_registrations_expires on public.temp_registrations (expires_at);
105	create index idx_temp_registrations_accessed on public.temp_registrations (accessed_at);
106	
107	
108	-- 3. Materialized View
109	
110	create materialized view public.daily_team_stats as
111	select
112	    a.date,
113	    u.team_id,
114	    u.generation,
115	    count(distinct case when a.type = 'in' then a.user_id end) as attendance_count
116	from attendances a
117	join users u on a.user_id = u.id
118	group by a.date, u.team_id, u.generation;
119	
120	-- 4. RLS (Row Level Security) & Policies
121	
122	alter table public.teams enable row level security;
123	alter table public.users enable row level security;
124	alter table public.attendances enable row level security;
125	alter table public.announcements enable row level security;
126	alter table public.user_edit_logs enable row level security;
127	alter table public.daily_logout_logs enable row level security;
128	alter table public.temp_registrations enable row level security;
129	
130	-- Helper function to check user role
131	create or replace function public.is_admin()
132	returns boolean
133	language sql
134	security definer
135	set search_path = public
136	as $$
137	    select coalesce((select role from public.users where id = auth.uid()), 0) = 1;
138	$$;
139	
140	-- Teams: Publicly readable
141	create policy "Allow all read access to teams" on public.teams for select using (true);
142	create policy "Allow admin to manage teams" on public.teams for all using (public.is_admin()) with check (public.is_admin());
143	
144	-- Users:
145	create policy "Users can see their own data" on public.users for select using (auth.uid() = id);
146	create policy "Admins can see all users" on public.users for select using (public.is_admin());
