1	'use server';
2	
3	import { createSupabaseAdminClient, createSupabaseServerClient } from '@/lib/supabase/server';
4	import { Tables } from '@/lib/types';
5	import { revalidatePath } from 'next/cache';
6	import { redirect } from 'next/navigation';
7	import { randomUUID } from 'crypto';
8	import { differenceInSeconds, startOfDay, endOfDay, subDays, format, startOfMonth, endOfMonth } from 'date-fns';
9	import { fetchMemberNickname } from '@/lib/name-api';
10	
11	// ========================================
12	// サービス層からの再エクスポート
13	// ========================================
14	
15	// 認証関連
16	export { signInWithDiscord, signOut } from '@/lib/services/auth.service';
17	
18	// ユーザー管理関連
19	export { 
20	  getAllUsersWithStatus,
21	  updateUserDisplayName,
22	  updateAllUserDisplayNames,
23	  updateUserCardId
24	} from '@/lib/services/user.service';
25	
26	// 勤怠管理関連
27	export {
28	  forceToggleAttendance,
29	  getAllDailyLogoutLogs,
30	  getMonthlyAttendanceSummary,
31	  getDailyAttendanceCounts,
32	  getDailyAttendanceDetails,
33	  getOverallStats
34	} from '@/lib/services/attendance.service';
35	
36	// チーム管理関連
37	export {
38	  getAllTeams,
39	  getTeamsWithMemberStatus,
40	  getTeamWithMembersStatus
41	  // createTeam, updateTeam, deleteTeam は型定義の問題で一時的にコメントアウト
42	} from '@/lib/services/team.service';
43	
44	// 登録管理関連
45	export {
46	  getTempRegistrations,
47	  getTempRegistrationByToken,
48	  deleteTempRegistration
49	  // completeTempRegistration は型の問題により actions.ts に実装
50	} from '@/lib/services/registration.service';
51	
52	// システム管理関連
53	export { forceLogoutAll } from '@/lib/services/system.service';
54	
55	// ========================================
56	// コアビジネスロジック（actions.tsに残す関数）
57	// ========================================
58	
59	type Member = Tables<'member', 'members'>;
60	type AttendanceUser = Tables<'attendance', 'users'>;
61	
62	/**
63	 * カードタッチで勤怠を記録
64	 * キオスク端末から呼び出される主要な関数
65	 */
66	export async function recordAttendance(cardId: string): Promise<{ 
67	  success: boolean; 
68	  message: string; 
69	  user: { display_name: string | null } | null; 
70	  type: 'in' | 'out' | null 
71	}> {
72	  const supabase = await createSupabaseAdminClient();
73	  
74	  const normalizedCardId = cardId.replace(/:/g, '').toLowerCase();
75	
76	  const { data: attendanceUser, error: attendanceUserError } = await supabase
77	    .schema('attendance')
78	    .from('users')
79	    .select('supabase_auth_user_id, card_id')
80	    .eq('card_id', normalizedCardId)
81	    .single();
82	
83	  if (attendanceUserError || !attendanceUser) {
84	    return { success: false, message: '未登録のカードです。', user: null, type: null };
85	  }
86	
87	  const userId = attendanceUser.supabase_auth_user_id;
88	  
89	  // member.members テーブルから Discord UID を取得
90	  const { data: memberData } = await supabase
91	    .schema('member')
92	    .from('members')
93	    .select('discord_uid')
94	    .eq('supabase_auth_user_id', userId)
95	    .single();
96	  
97	  let userDisplayName = '名無しさん';
98	  
99	  // Discord UIDがある場合、APIから本名を取得
100	  if (memberData?.discord_uid) {
101	    const { data: nickname } = await fetchMemberNickname(memberData.discord_uid);
102	    if (nickname) {
103	      userDisplayName = nickname;
104	    }
105	  }
106	
107	  const today = format(new Date(), 'yyyy-MM-dd');
108	  const now = new Date();
109	
110	  const { data: recentAttendances } = await supabase
111	    .schema('attendance')
112	    .from('attendances')
113	    .select('*')
114	    .eq('user_id', userId)
115	    .eq('date', today)
116	    .order('timestamp', { ascending: false })
117	    .limit(1);
118	
119	  let attendanceType: 'in' | 'out' = 'in';
120	  if (recentAttendances && recentAttendances.length > 0) {
121	    const lastType = recentAttendances[0].type;
122	    attendanceType = lastType === 'in' ? 'out' : 'in';
123	  }
124	
125	  const { error: insertError } = await supabase
126	    .schema('attendance')
127	    .from('attendances')
128	    .insert({
129	      user_id: userId,
130	      type: attendanceType,
131	      timestamp: now.toISOString(),
132	      date: today,
133	    });
134	
135	  if (insertError) {
136	    console.error('Error inserting attendance:', insertError);
137	    return { 
138	      success: false, 
139	      message: '勤怠記録に失敗しました。', 
140	      user: { display_name: userDisplayName }, 
141	      type: null 
142	    };
143	  }
144	
145	  const message = attendanceType === 'in' ? `${userDisplayName}さん、おはようございます!` : `${userDisplayName}さん、お疲れ様でした!`;
146	  
147	  revalidatePath('/dashboard');
148	  revalidatePath('/admin');
