169	            const newRemaining = qrExpiry - Date.now();
170	            if (newRemaining <= 0) {
171	                clearInterval(timer);
172	                onExpire();
173	            }
174	            setRemaining(newRemaining);
175	        }, 1000);
176	        return () => clearInterval(timer);
177	    }, [qrExpiry, onExpire]);
178	
179	    const minutes = Math.floor(remaining / 60000);
180	    const seconds = Math.floor((remaining % 60000) / 1000).toString().padStart(2, '0');
181	
182	    return (
183	        <p className="mt-2 text-lg">有効期限: あと{minutes}分{seconds}秒</p>
184	    );
185	});
186	QrTimer.displayName = 'QrTimer';
