429	          {kioskState === 'error' && <ErrorScreen message={message} subMessage={subMessage} />}
430	          {kioskState === 'register' && <RegisterScreen message={message} subMessage={subMessage} />}
431	          {kioskState === 'qr' && qrToken && <QrScreen qrToken={qrToken} qrExpiry={qrExpiry} onExpire={resetToIdle} />}
432	          {(kioskState === 'loading' || kioskState === 'processing') && <ProcessingScreen state={kioskState} />}
433	        </div>
